-- Phase 10b task 1: translations. Generated by drizzle-kit, then trimmed by
-- hand. `gesture_keyword` gains `locale` and its primary key becomes
-- (gesture_id, locale, keyword), which needs a rebuild: nothing references
-- `gesture_keyword` and it has no trigger, so dropping it cascades nothing.
-- Every existing row is a Dutch keyword (nl is the default language), also
-- the column default. The `PRAGMA foreign_keys` toggles drizzle-kit generates
-- are no-ops in D1's migration transaction and are left out.
CREATE TABLE `category_translation` (
	`category_id` text NOT NULL,
	`locale` text NOT NULL,
	`name` text NOT NULL,
	`updated_by` text,
	`updated_at` integer NOT NULL,
	PRIMARY KEY(`category_id`, `locale`),
	FOREIGN KEY (`category_id`) REFERENCES `category`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`locale`) REFERENCES `language`(`code`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`updated_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "category_translation_name_length_check" CHECK(length("name") BETWEEN 1 AND 200)
);
--> statement-breakpoint
CREATE INDEX `category_translation_locale_idx` ON `category_translation` (`locale`,`category_id`);--> statement-breakpoint
CREATE INDEX `category_translation_updated_by_idx` ON `category_translation` (`updated_by`);--> statement-breakpoint
CREATE TABLE `gesture_translation` (
	`gesture_id` text NOT NULL,
