	`name` text NOT NULL,
	`description` text DEFAULT '' NOT NULL,
	`updated_by` text,
	`updated_at` integer NOT NULL,
	PRIMARY KEY(`gesture_id`, `locale`),
	FOREIGN KEY (`gesture_id`) REFERENCES `gesture`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`locale`) REFERENCES `language`(`code`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`updated_by`) REFERENCES `user`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "gesture_translation_name_length_check" CHECK(length("name") BETWEEN 1 AND 200)
);
--> statement-breakpoint
CREATE INDEX `gesture_translation_locale_idx` ON `gesture_translation` (`locale`,`gesture_id`);--> statement-breakpoint
CREATE INDEX `gesture_translation_updated_by_idx` ON `gesture_translation` (`updated_by`);--> statement-breakpoint
CREATE TABLE `__new_gesture_keyword` (
